        for c in range(w):
            if grid[r][c]==color:
                q.append((r,c)); seen.add((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==0:
                seen.add((nr,nc)); out[nr][nc]=color; q.append((nr,nc))
    return out
